function policy(obs, params, mem) {
  var P = params;
  var LL = 0.51, HIPY = -0.37;
  var TQH = 195.0, TQK = 216.0;
  var HMIN = -0.86, HMAX = 1.16, KMIN = -1.66, KMAX = -0.08;
  var WGT = 64.14 * 9.41;

  function cl(v, a, b) {
    if (!(v > -1e9) || !(v < 1e9)) return 0.5 * (a + b);
    return v < a ? a : (v > b ? b : v);
  }

  var tA = obs[0], tS = obs[1], vx = obs[2], vy = obs[3], hgt = obs[4];
  var hA = obs[5], hAd = obs[6], kA = obs[7], kAd = obs[8], fA = obs[9];
  var hB = obs[10], hBd = obs[11], kB = obs[12], kBd = obs[13], fB = obs[14];
  var a1 = obs[15], a2 = obs[16], a3 = obs[17], a4 = obs[18], tt = obs[19];
  if (!(tt > -1e9) || !(tt < 1e9)) tt = 0;

  function groundAt(x) {
    if (x <= 0) return 0;
    if (x <= 0.5) return a1 * x * 2;
    if (x <= 1) return a1 + (a2 - a1) * (x - 0.5) * 2;
    if (x <= 2) return a2 + (a3 - a2) * (x - 1);
    return a3 + (a4 - a3) * (x - 2) * 0.5;
  }

  function footCl(qh, qk) {
    var p1 = mem.sG * qh, p2 = mem.sG * qk;
    var fx = LL * Math.sin(p1) + LL * Math.sin(p1 + p2);
    var fy = HIPY - LL * Math.cos(p1) - LL * Math.cos(p1 + p2);
    var ca = Math.cos(tA), sa = Math.sin(tA);
    var wx = fx * ca + fy * sa, wy = -fx * sa + fy * ca;
    return hgt + wy - groundAt(wx + 0.12);
  }

  // ---------- persistent state + one-shot sign probe ----------
  if (mem.i === undefined) {
    mem.i = 0; mem.sA = 1; mem.sG = 1; mem.probing = 1;
    mem.phase = 0; mem.pErr = 0;
    mem.pfA = fA > 0.5 ? 1 : 0; mem.pfB = fB > 0.5 ? 1 : 0;
    mem.h0 = 0.5 * (hA + hB); mem.t0 = tA;
  }
  mem.i++;

  if (mem.probing) {
    var dh = 0.5 * (hA + hB) - mem.h0;
    var dT = tA - mem.t0;
    if (mem.i > 1 && Math.abs(dh) > 3e-4 && Math.abs(dT) > 1.2e-3) {
      mem.sA = dh > 0 ? 1 : -1;
      mem.sG = (dh * dT) > 0 ? 1 : -1;
      mem.probing = 0;
    } else if (mem.i >= 8) {
      mem.probing = 0;
    } else {
      return [0.035, 0, 0.035, 0];
    }
  }

  // ---------- parameters ----------
  var freq = cl(P[0], 0.4, 3.2);
  var duty = cl(P[1], 0.25, 0.92);
  var thTD = cl(P[2], 0.02, 0.9);
  var thTO = cl(P[3], -0.9, -0.02);
  var dTD = cl(P[4], 0.85, 1.016);
  var comp = cl(P[5], 0.0, 0.16);
  var dSwM = cl(P[6], 0.70, 0.98);
  var kp = cl(P[7], 40, 1200);
  var kdTm = cl(P[8], 0.005, 0.25);
  var ffG = cl(P[9], 0, 2.5);
  var kpT = cl(P[10], 10, 1500);
  var kdT2 = cl(P[11], 5, 800);
  var lean = cl(P[12], -0.35, 0.3);
  var kFbTh = cl(P[13], 0, 3.5);
  var kFbV = cl(P[14], 0, 2.0);
  var sFit = cl(P[15], 0.6, 1.4);
  var tStart = cl(P[16], 0.08, 1.5);
  var kLift = cl(P[17], 0, 4);
  var clrT = cl(P[18], 0, 0.35);
  var swSh = cl(P[19], 1.0, 4.0);
  var kd = kp * kdTm;
  var tRamp = 0.45, dStand = 0.95, syncG = 0.35, stSh = 1.2;

  var vDes = sFit * 2.0 * dTD * (Math.sin(thTD) - Math.sin(thTO)) * freq;

  // ---------- phase ----------
  var amp = 0;
  if (tt >= tStart) {
    var ar = cl((tt - tStart) / tRamp, 0, 1);
    amp = ar * ar * (3 - 2 * ar);
    mem.phase += freq / 60 * (1 + 2 * syncG * mem.pErr);
    mem.pErr *= Math.exp(-3 * freq / 60);
    var cA = fA > 0.5 ? 1 : 0, cB = fB > 0.5 ? 1 : 0;
    if (cA === 1 && mem.pfA === 0) {
      var pa = mem.phase - Math.floor(mem.phase);
      var e1 = -pa; if (e1 > 0.5) e1 -= 1; if (e1 < -0.5) e1 += 1;
      mem.pErr = e1;
    }
    if (cB === 1 && mem.pfB === 0) {
      var pb = mem.phase + 0.5; pb = pb - Math.floor(pb);
      var e2 = -pb; if (e2 > 0.5) e2 -= 1; if (e2 < -0.5) e2 += 1;
      mem.pErr = e2;
    }
    mem.pfA = cA; mem.pfB = cB;
  }
  var phA = mem.phase - Math.floor(mem.phase);
  var phB = phA + 0.5; if (phB >= 1) phB -= 1;

  // ---------- load sharing (feedforward) ----------
  var stA = cl((duty + 0.04 - phA) / 0.08, 0, 1);
  var stB = cl((duty + 0.04 - phB) / 0.08, 0, 1);
  stA = 0.5 + (stA - 0.5) * amp;
  stB = 0.5 + (stB - 0.5) * amp;
  var tot = stA + stB; if (tot < 0.25) tot = 0.25;
  var FyA = WGT * stA / tot * ffG;
  var FyB = WGT * stB / tot * ffG;

  var swA = phA >= duty ? Math.max(0, Math.sin(Math.PI * (phA - duty) / (1 - duty))) : 0;
  var swB = phB >= duty ? Math.max(0, Math.sin(Math.PI * (phB - duty) / (1 - duty))) : 0;

  // ---------- gait targets in (leg length, leg angle) ----------
  var dA, th1, dB, th2, u, v, s;
  if (phA < duty) {
    u = phA / duty;
    dA = dTD - comp * Math.pow(Math.max(0, Math.sin(Math.PI * u)), stSh);
    th1 = thTD + (thTO - thTD) * u;
  } else {
    v = (phA - duty) / (1 - duty);
    s = v * v * (3 - 2 * v);
    dA = dTD - (dTD - dSwM) * Math.pow(Math.max(0, Math.sin(Math.PI * v)), swSh);
    th1 = thTO + (thTD - thTO) * s;
  }
  if (phB < duty) {
    u = phB / duty;
    dB = dTD - comp * Math.pow(Math.max(0, Math.sin(Math.PI * u)), stSh);
    th2 = thTD + (thTO - thTD) * u;
  } else {
    v = (phB - duty) / (1 - duty);
    s = v * v * (3 - 2 * v);
    dB = dTD - (dTD - dSwM) * Math.pow(Math.max(0, Math.sin(Math.PI * v)), swSh);
    th2 = thTO + (thTD - thTO) * s;
  }

  // ---------- foot placement / speed feedback ----------
  var dTh = kFbTh * (lean - tA) + kFbV * (vx - vDes);
  dTh = cl(dTh, -0.32, 0.32) * amp;
  th1 += dTh; th2 += dTh;

  // ---------- reactive swing lift for terrain / hurdles ----------
  if (kLift > 0.001 && clrT > 0.001) {
    if (swA > 0.01) {
      var clA = footCl(hA, kA);
      if (clA < clrT) dA = cl(dA - kLift * (clrT - clA) * swA, 0.62, 1.016);
    }
    if (swB > 0.01) {
      var clB = footCl(hB, kB);
      if (clB < clrT) dB = cl(dB - kLift * (clrT - clB) * swB, 0.62, 1.016);
    }
  }

  // ---------- smooth start ----------
  if (amp < 1) {
    dA = dStand + (dA - dStand) * amp;
    dB = dStand + (dB - dStand) * amp;
    th1 *= amp; th2 *= amp;
  }

  // ---------- inverse kinematics (reported joint space) ----------
  var acA = Math.acos(cl(dA / 1.02, 0, 1));
  var acB = Math.acos(cl(dB / 1.02, 0, 1));
  var qHA = cl(mem.sG * th1 + acA, HMIN, HMAX);
  var qKA = cl(-2 * acA, KMIN, KMAX);
  var qHB = cl(mem.sG * th2 + acB, HMIN, HMAX);
  var qKB = cl(-2 * acB, KMIN, KMAX);

  // ---------- torso balance (reaction torque through both hips) ----------
  var tb = -(kpT * (tA - lean) + kdT2 * tS) * mem.sG;
  tb = cl(tb, -170, 170);

  // ---------- motor commands ----------
  var tH, tK, uHA, uKA, uHB, uKB;
  tH = kp * (qHA - hA) - kd * hAd;
  tK = kp * (qKA - kA) - kd * kAd;
  tH += -FyA * (LL * Math.sin(hA) + LL * Math.sin(hA + kA));
  tK += -FyA * (LL * Math.sin(hA + kA));
  tH += tb;
  uHA = mem.sA * cl(tH / TQH, -1, 1);
  uKA = mem.sA * cl(tK / TQK, -1, 1);

  tH = kp * (qHB - hB) - kd * hBd;
  tK = kp * (qKB - kB) - kd * kBd;
  tH += -FyB * (LL * Math.sin(hB) + LL * Math.sin(hB + kB));
  tK += -FyB * (LL * Math.sin(hB + kB));
  tH += tb;
  uHB = mem.sA * cl(tH / TQH, -1, 1);
  uKB = mem.sA * cl(tK / TQK, -1, 1);

  return [uHA, uKA, uHB, uKB];
}

function learn(lab) {
  var D = 20;
  var LO = [0.70, 0.40, 0.12, -0.75, 0.90, 0.00, 0.70, 80, 0.012, 0.0, 30, 8, -0.25, 0.0, 0.0, 0.70, 0.15, 0.0, 0.00, 1.0];
  var HI = [2.60, 0.85, 0.75, -0.10, 1.016, 0.14, 0.98, 900, 0.18, 2.2, 1200, 600, 0.20, 3.0, 1.5, 1.30, 1.30, 3.0, 0.30, 4.0];
  var MD = [1.50, 0.55, 0.30, -0.29, 0.975, 0.07, 0.85, 250, 0.05, 1.0, 300, 130, -0.03, 0.7, 0.35, 1.0, 0.45, 0.9, 0.10, 1.8];

  var t0 = 0;
  try { t0 = Date.now(); } catch (e) { t0 = 0; }
  function out() {
    if (!t0) return false;
    try { return (Date.now() - t0) > 150000; } catch (e) { return false; }
  }

  var cache = {};
  var best = null, bestS = -Infinity;

  function clampTo(x) {
    var y = new Array(D);
    for (var i = 0; i < D; i++) {
      var v = x[i];
      if (!(v > -1e9) || !(v < 1e9)) v = MD[i];
      y[i] = v < LO[i] ? LO[i] : (v > HI[i] ? HI[i] : v);
    }
    return y;
  }

  function ev(x) {
    var p = clampTo(x);
    var key = '';
    for (var i = 0; i < D; i++) key += Math.round(p[i] * 1e4) + '|';
    if (cache[key] !== undefined) return cache[key];
    if (out() || lab.trialsLeft() <= 2) return -Infinity;
    var r = null;
    try { r = lab.trial(p); } catch (e) { r = null; }
    var s = -1e7;
    if (r && typeof r.distance === 'number' && isFinite(r.distance)) {
      s = r.distance;
      if (r.outcome === 'finished') s += 1.2;
      else if (r.outcome === 'invalid' || r.outcome === 'error') s -= 500;
      if (typeof r.time === 'number' && isFinite(r.time)) s += 0.04 * r.time;
      if (typeof r.energy === 'number' && isFinite(r.energy)) s -= 0.00002 * r.energy;
    }
    cache[key] = s;
    if (s > bestS) { bestS = s; best = p.slice(); }
    return s;
  }

  var gsp = null;
  function gauss() {
    if (gsp !== null) { var vv = gsp; gsp = null; return vv; }
    var u1 = Math.random(), u2 = Math.random();
    if (u1 < 1e-9) u1 = 1e-9;
    var rr = Math.sqrt(-2 * Math.log(u1));
    gsp = rr * Math.sin(2 * Math.PI * u2);
    return rr * Math.cos(2 * Math.PI * u2);
  }

  function chol(A) {
    var n = A.length, Lm = [], i, j, k, sm;
    for (i = 0; i < n; i++) Lm.push(new Array(n).fill(0));
    for (i = 0; i < n; i++) {
      for (j = 0; j <= i; j++) {
        sm = A[i][j];
        for (k = 0; k < j; k++) sm -= Lm[i][k] * Lm[j][k];
        if (i === j) Lm[i][i] = Math.sqrt(Math.max(sm, 1e-12));
        else Lm[i][j] = sm / Lm[j][j];
      }
    }
    return Lm;
  }

  // ---- hand-designed probes (hedge against a bad prior) ----
  var probes = [
    MD,
    [2.00, 0.55, 0.30, -0.29, 0.975, 0.06, 0.85, 420, 0.05, 1.1, 420, 160, -0.03, 0.7, 0.35, 1.0, 0.45, 0.9, 0.10, 1.8],
    [1.15, 0.62, 0.28, -0.26, 0.985, 0.05, 0.88, 170, 0.06, 1.0, 220, 110, -0.02, 0.5, 0.25, 1.0, 0.45, 0.9, 0.10, 1.8],
    [1.55, 0.72, 0.26, -0.25, 0.99, 0.04, 0.88, 300, 0.05, 1.1, 320, 140, -0.03, 0.6, 0.30, 1.0, 0.45, 0.7, 0.08, 1.9],
    [1.65, 0.50, 0.34, -0.33, 0.965, 0.09, 0.82, 350, 0.045, 1.2, 380, 150, -0.05, 0.9, 0.40, 1.05, 0.45, 1.0, 0.12, 1.6],
    [1.30, 0.52, 0.30, -0.29, 0.985, 0.055, 0.86, 210, 0.055, 1.05, 260, 120, -0.02, 0.65, 0.30, 1.0, 0.60, 0.8, 0.09, 2.1]
  ];
  for (var pi = 0; pi < probes.length; pi++) {
    if (out() || lab.trialsLeft() <= 2) break;
    ev(probes[pi]);
  }
  if (best === null) best = MD.slice();

  // ---- full-covariance cross-entropy search ----
  var mean = best.slice();
  var cov = [], i, j, k;
  for (i = 0; i < D; i++) {
    cov.push(new Array(D).fill(0));
    var s0 = 0.34 * (HI[i] - LO[i]);
    cov[i][i] = s0 * s0;
  }
  var nPop = 45, nEl = 8;
  var noImp = 0, lastBest = bestS;

  for (var it = 0; it < 10; it++) {
    if (out() || lab.trialsLeft() < nPop + 4) break;
    var Lm = chol(cov);
    var samp = [], sc = [];
    for (k = 0; k < nPop; k++) {
      var z = [], x = [], vv;
      for (i = 0; i < D; i++) z.push(gauss());
      for (i = 0; i < D; i++) {
        vv = mean[i];
        for (j = 0; j <= i; j++) vv += Lm[i][j] * z[j];
        x.push(vv);
      }
      samp.push(x);
      sc.push(ev(x));
    }
    var idx = [];
    for (k = 0; k < nPop; k++) idx.push(k);
    idx.sort(function (a, b) { return sc[b] - sc[a]; });

    var nm = new Array(D).fill(0);
    for (var e = 0; e < nEl; e++) for (i = 0; i < D; i++) nm[i] += samp[idx[e]][i] / nEl;

    var nc = [];
    for (i = 0; i < D; i++) nc.push(new Array(D).fill(0));
    for (var e2 = 0; e2 < nEl; e2++) {
      var xx = samp[idx[e2]];
      for (i = 0; i < D; i++) for (j = 0; j < D; j++) {
        nc[i][j] += (xx[i] - nm[i]) * (xx[j] - nm[j]) / (nEl - 1);
      }
    }
    var bl = 0.72;
    for (i = 0; i < D; i++) for (j = 0; j < D; j++) {
      nc[i][j] = bl * nc[i][j] + (1 - bl) * (i === j ? cov[i][j] : 0);
    }
    for (i = 0; i < D; i++) {
      var fl = 0.018 * (HI[i] - LO[i]);
      if (nc[i][i] < fl * fl) nc[i][i] = fl * fl;
    }
    for (i = 0; i < D; i++) mean[i] = 0.8 * nm[i] + 0.2 * mean[i];
    cov = nc;

    if (bestS > lastBest + 1e-6) { lastBest = bestS; noImp = 0; }
    else {
      noImp++;
      if (noImp >= 2) {
        for (i = 0; i < D; i++) for (j = 0; j < D; j++) cov[i][j] *= 1.7;
        for (i = 0; i < D; i++) mean[i] = 0.6 * best[i] + 0.4 * mean[i];
        noImp = 0;
      }
    }
  }

  // ---- local (1+1) polish ----
  var cur = best.slice(), curS = bestS;
  var step = [];
  for (i = 0; i < D; i++) step.push(0.05 * (HI[i] - LO[i]));
  for (var q = 0; q < 300; q++) {
    if (out() || lab.trialsLeft() <= 3) break;
    if (bestS > curS) { cur = best.slice(); curS = bestS; }
    var xp = cur.slice();
    for (i = 0; i < D; i++) xp[i] += step[i] * gauss();
    var sp = ev(xp);
    if (sp > curS) {
      curS = sp; cur = clampTo(xp);
      for (i = 0; i < D; i++) step[i] *= 1.12;
    } else {
      for (i = 0; i < D; i++) step[i] *= 0.985;
    }
    for (i = 0; i < D; i++) {
      var mx = 0.25 * (HI[i] - LO[i]);
      if (step[i] > mx) step[i] = mx;
    }
  }
  return best;
}

function policy(obs, params, mem) {
  var P = params;
  var LL = 0.51, HIPY = -0.37;
  var TQH = 195, TQK = 216;
  var HMN = -0.86, HMX = 1.16, KMN = -1.66, KMX = -0.08;
  var W = 64.14 * 9.41;

  function cl(v, a, b) {
    if (!(v > -1e9) || !(v < 1e9)) return 0.5 * (a + b);
    return v < a ? a : v > b ? b : v;
  }

  var tA = obs[0], tS = obs[1], vx = obs[2], vy = obs[3], hgt = obs[4];
  var hA = obs[5], hAd = obs[6], kA = obs[7], kAd = obs[8], fA = obs[9];
  var hB = obs[10], hBd = obs[11], kB = obs[12], kBd = obs[13], fB = obs[14];
  var a1 = obs[15], a2 = obs[16], a3 = obs[17], a4 = obs[18], tt = obs[19];
  if (!(tt > -1e9) || !(tt < 1e9)) tt = 0;

  function gnd(x) {
    if (x <= 0) return 0;
    if (x <= 0.5) return a1 * x * 2;
    if (x <= 1) return a1 + (a2 - a1) * (x - 0.5) * 2;
    if (x <= 2) return a2 + (a3 - a2) * (x - 1);
    return a3 + (a4 - a3) * (x - 2) * 0.5;
  }

  function fclr(qh, qk) {
    var p1 = mem.sG * qh, p2 = mem.sG * qk;
    var fx = LL * Math.sin(p1) + LL * Math.sin(p1 + p2);
    var fy = HIPY - LL * Math.cos(p1) - LL * Math.cos(p1 + p2);
    var ca = Math.cos(tA), sa = Math.sin(tA);
    return hgt + (-fx * sa + fy * ca) - gnd(fx * ca + fy * sa + 0.15);
  }

  if (mem.i === undefined) {
    mem.i = 0; mem.sA = 1; mem.sG = 1; mem.probing = 1;
    mem.phase = 0; mem.pErr = 0;
    mem.pfA = fA > 0.5 ? 1 : 0; mem.pfB = fB > 0.5 ? 1 : 0;
    mem.h0 = 0.5 * (hA + hB); mem.t0 = tA;
  }
  mem.i++;

  if (mem.probing) {
    var dh = 0.5 * (hA + hB) - mem.h0;
    var dT = tA - mem.t0;
    if (mem.i > 1 && Math.abs(dh) > 1e-4 && Math.abs(dT) > 4e-4) {
      mem.sA = dh > 0 ? 1 : -1;
      mem.sG = (dh * dT) > 0 ? 1 : -1;
      mem.probing = 0;
    } else if (mem.i >= 10) {
      mem.probing = 0;
    } else {
      return [0.08, 0, 0.08, 0];
    }
  }

  var freq = cl(P[0], 0.7, 3.5);
  var duty = cl(P[1], 0.28, 0.82);
  var thTD = cl(P[2], 0.08, 0.82);
  var thTO = cl(P[3], -0.82, -0.06);
  var dTD = cl(P[4], 0.82, 1.015);
  var comp = cl(P[5], 0, 0.16);
  var dSwM = cl(P[6], 0.62, 0.98);
  var kp = cl(P[7], 60, 1100);
  var kdR = cl(P[8], 0.012, 0.28);
  var ffG = cl(P[9], 0.4, 2.4);
  var lean = cl(P[10], -0.28, 0.25);
  var kpT = cl(P[11], 30, 1300);
  var kdT = cl(P[12], 6, 700);
  var kFbTh = cl(P[13], 0, 4);
  var kFbV = cl(P[14], 0, 2.5);
  var kHgt = cl(P[15], 0, 5);
  var kLift = cl(P[16], 0, 4);
  var clrT = cl(P[17], 0, 0.32);
  var kd = kp * kdR;

  var vDes = dTD * (Math.sin(thTD) - Math.sin(thTO)) * freq / duty;

  var amp = 0, tStart = 0.15, tRamp = 0.35;
  if (tt >= tStart) {
    var ar = cl((tt - tStart) / tRamp, 0, 1);
    amp = ar * ar * (3 - 2 * ar);
    mem.phase += freq / 60 * (1 + 0.5 * mem.pErr);
    var cA = fA > 0.5 ? 1 : 0, cB = fB > 0.5 ? 1 : 0;
    if (cA === 1 && mem.pfA === 0) {
      var pa = mem.phase - Math.floor(mem.phase);
      var e = -pa; if (e > 0.5) e -= 1; if (e < -0.5) e += 1;
      mem.pErr = e;
    }
    if (cB === 1 && mem.pfB === 0) {
      var pb = mem.phase + 0.5; pb -= Math.floor(pb);
      var e2 = -pb; if (e2 > 0.5) e2 -= 1; if (e2 < -0.5) e2 += 1;
      mem.pErr = e2;
    }
    mem.pfA = cA; mem.pfB = cB;
