    [1.8,0.70,0.11,0.06,0.95,1.1,0.5]
  ];
  for (var ci=0; ci<cfg.length; ci++) {
    var c = cfg[ci];
    seeds.push(walkSeed(c[0],c[1],c[2],c[3],c[4],c[5],c[6], 1, 0));
    seeds.push(walkSeed(c[0],c[1],c[2],c[3],c[4],c[5],c[6], -1, 0));
    if (ci % 3 === 0) {
      seeds.push(walkSeed(c[0],c[1],c[2],c[3],c[4],c[5],c[6], 1, 0.7));
      seeds.push(walkSeed(c[0],c[1],c[2],c[3],c[4],c[5],c[6], -1, 0.7));
    }
  }

  var reserve = 8;
  for (var si=0; si<seeds.length && lab.trialsLeft()>reserve; si++) {
    evalP(seeds[si]);
  }

  if (!bestFull && lab.trialsLeft() > 120) {
    for (var q0=0; q0<45 && lab.trialsLeft()>reserve; q0++) {
      var base0 = seeds[Math.floor(Math.random()*seeds.length)];
      var c0 = new Array(n);
      for (var i0=0;i0<n;i0++) {
        var range0 = HI[i0]-LO[i0];
        c0[i0] = cl(base0[i0] + randn()*range0*0.12,LO[i0],HI[i0]);
      }
      evalP(c0);
    }
  }

  var mean = bestFull ? bestFull.slice() : (bestAll ? bestAll.slice() : DEF.slice());
  var sig = new Array(n);
  for (var i1=0;i1<n;i1++) sig[i1] = (HI[i1]-LO[i1])*0.18;

  var popSize = 24;
  var stallCount = 0;
  var lastBest = bestAllScore;

  while (lab.trialsLeft() > (bestFull ? 8 : 4) && evals < 985) {
    var P = Math.min(popSize, lab.trialsLeft()-4);
    if (P < 6) break;

    var pop = [], scores = [];

    for (var j=0;j<P;j++) {
      var cand;
      if (j === 0 && bestAll) cand = bestAll.slice();
      else if (j === 1 && bestFull) cand = bestFull.slice();
      else if (j === 2) cand = mean.slice();
      else {
        var r0 = Math.random();
        if (r0 < 0.10) {
          cand = new Array(n);
          for (var i2=0;i2<n;i2++) cand[i2] = LO[i2] + Math.random()*(HI[i2]-LO[i2]);
        } else {
          var base = mean;
          if (bestFull && r0 < 0.22) base = bestFull;
          else if (bestAll && r0 < 0.28) base = bestAll;
          cand = mutate(base,sig,1);
        }
      }
      cand = norm(cand);
      pop.push(cand);
      scores.push(evalP(cand));
    }

    var idx = [];
    for (var j2=0;j2<P;j2++) idx.push(j2);
    idx.sort(function(a,b){ return scores[b]-scores[a]; });

    var E = Math.max(3,Math.floor(P*0.30));
    if (E > P) E = P;

    var newMean = new Array(n);
    for (var i3=0;i3<n;i3++) newMean[i3] = 0;
    var wsum = 0;
    for (var k=0;k<E;k++) {
      var w = Math.pow(0.7,k);
      var pc = pop[idx[k]];
      for (var i4=0;i4<n;i4++) newMean[i4] += pc[i4]*w;
      wsum += w;
    }
    for (var i5=0;i5<n;i5++) newMean[i5] /= wsum;

    var newSig = new Array(n);
    for (var i6=0;i6<n;i6++) {
      var vv = 0, ws = 0;
      for (var k2=0;k2<E;k2++) {
        var w2 = Math.pow(0.7,k2);
        var dd = pop[idx[k2]][i6] - newMean[i6];
        vv += w2*dd*dd;
        ws += w2;
      }
      vv = Math.sqrt(vv/ws);
      var rng = HI[i6]-LO[i6];
      var ns = 0.40*sig[i6] + 0.60*vv;
      if (!isFinite(ns) || ns < rng*0.003) ns = rng*0.003;
      if (ns > rng*0.6) ns = rng*0.6;
      newSig[i6] = ns;
    }

    mean = norm(newMean);
    sig = newSig;

    if (bestAllScore > lastBest + 1e-9) {
      lastBest = bestAllScore;
      stallCount = 0;
    } else {
      stallCount++;
    }

    if (stallCount > 7) {
      if (bestFull && Math.random() < 0.6) mean = bestFull.slice();
      else if (bestAll) mean = bestAll.slice();
      for (var i7=0;i7<n;i7++) {
        var rng2 = HI[i7]-LO[i7];
        if (sig[i7] < rng2*0.15) sig[i7] = rng2*0.15;
        if (sig[i7] > rng2*0.7) sig[i7] = rng2*0.7;
      }
      stallCount = 0;
    }
  }

  var chosen = bestFull ? bestFull.slice() : (bestAll ? bestAll.slice() : DEF.slice());

  if (bestFull && lab.trialsLeft() > 3 && fullPool.length > 0) {
    fullPool.sort(function(a,b){
      if (b.d !== a.d) return b.d-a.d;
      return b.t-a.t;
    });

    var cands = [];
    for (var cc=0; cc<fullPool.length && cands.length<10; cc++) {
      var pp = fullPool[cc].p;
      var dup = false;
      for (var cj=0;cj<cands.length;cj++) {
        if (distNorm(pp,cands[cj].p) < 0.025) { dup = true; break; }
      }
      if (!dup) cands.push(fullPool[cc]);
    }

    var pertSig = new Array(n);
    for (var i8=0;i8<n;i8++) pertSig[i8] = (HI[i8]-LO[i8])*0.035;

    var chosenRob = cands.length ? cands[0].p.slice() : chosen;
    var bestRob = -1e100;

    for (var ci2=0; ci2<cands.length; ci2++) {
      var C = cands[ci2];
      var neigh = 0;
      for (var q1=0;q1<fullPool.length;q1++) {
        if (fullPool[q1] === C) continue;
        if (distNorm(C.p,fullPool[q1].p) < 0.06) neigh++;
      }

      var surv = 0;
      var tests = Math.min(2, Math.max(0, lab.trialsLeft()-2));
      for (var q2=0;q2<tests;q2++) {
        var cm = mutate(C.p,pertSig,1);
        var sm = evalP(cm);
        if (sm >= 1e6) surv++;
      }

      var rs = C.d*(1 + 0.02*Math.min(10,neigh) + 0.06*surv) + 0.01*C.t;
      if (rs > bestRob) {
        bestRob = rs;
        chosenRob = C.p.slice();
      }
    }
    chosen = chosenRob;
  }

  return norm(chosen);
}

function policy(obs, params, mem) {
  var DEF = [1.35,0.62,0.85,1.0,0.03,0.0,0.20,-0.35,-0.05,1.32,0.80,0.10,1.0,12,1.5,16,2.0,1.0,-0.03,2.0,0.4,0.5,0.7,0.10,0.15,0.0,0.5,0.45,0.6,0.20,0.05,0.0,0.0,0.4];
  var n = DEF.length;
  var P = (params && typeof params.length === "number" && params.length >= n) ? params : DEF;

  function cl(v,a,b) { return v<a?a:(v>b?b:v); }
  function num(v,d) { return (typeof v === "number" && isFinite(v)) ? v : d; }
  function g(i) { var v = P[i]; return (typeof v === "number" && isFinite(v)) ? v : DEF[i]; }

  var f = cl(g(0),0.2,4.0);
  var duty = cl(g(1),0.30,0.92);
  var vDes = cl(g(2),-0.5,3.0);
  var stepGain = cl(g(3),0.0,2.8);
  var stepMin = cl(g(4),0.0,0.5);
  var xOff = cl(g(5),-0.35,0.35);
  var footVelGain = cl(g(6),-2.0,2.0);
  var footPhiGain = cl(g(7),-3.5,3.5);
  var footSpinGain = cl(g(8),-2.5,2.5);
  var Hdes = cl(g(9),0.85,1.60);
  var heightGain = cl(g(10),0.0,5.0);
  var lift = cl(g(11),0.0,0.5);
  var terrainLift = cl(g(12),0.0,3.0);
  var hipKp = cl(g(13),0.2,45.0);
  var hipKd = cl(g(14),0.0,7.0);
  var kneeKp = cl(g(15),0.2,70.0);
  var kneeKd = cl(g(16),0.0,9.0);
  var hipComp = cl(g(17),-1.5,2.5);
  var phiDes = cl(g(18),-0.6,0.5);
  var balPhi = cl(g(19),-15.0,15.0);
  var balSpin = cl(g(20),-7.0,7.0);
  var balVel = cl(g(21),-7.0,7.0);
  var contactWeight = cl(g(22),0.0,1.0);
  var stanceExt = cl(g(23),-0.7,1.2);
  var swingBend = cl(g(24),-0.3,1.2);
  var hipSwing = cl(g(25),-0.7,0.7);
  var legOffset = cl(g(26),0.0,0.9);
  var rampTime = Math.max(0.04,g(27));
  var terrainBody = cl(g(28),0.0,2.5);
  var contactRetract = cl(g(29),0.0,1.5);
  var stancePush = cl(g(30),-0.2,0.6);
  var hipBias = cl(g(31),-0.5,0.5);
  var kneeBias = cl(g(32),-1.0,1.0);
  var dropGain = cl(g(33),0.0,2.0);

  var phi = num(obs[0],0);
  var spin = num(obs[1],0);
  var vx = num(obs[2],0);
  var vy = num(obs[3],0);
  var height = num(obs[4],0);
  var t = num(obs[19],0);

  var a1 = num(obs[15],0);
  var a2 = num(obs[16],0);
  var a3 = num(obs[17],0);
  var a4 = num(obs[18],0);

  var obstacle = Math.max(0,a1,0.8*a2,0.55*a3,0.35*a4);
  var drop = Math.max(0,-a1,-0.8*a2,-0.55*a3,-0.35*a4);

  var late = cl((t-10.0)/1.2,0.0,1.0);
  var vEff = vDes*(1.0-0.10*late);

  var ramp = cl((t+0.02)/rampTime,0.0,1.0);
  ramp = ramp*ramp*(3.0-2.0*ramp);

  var dBase = (Hdes-0.37) + heightGain*(Hdes-height) + terrainBody*obstacle;
  dBase = cl(dBase,0.35,1.03);

  var A = stepMin + stepGain*(vEff*duty/(2.0*Math.max(0.10,f)));
  A = cl(A,0.0,0.55);

  var lean = phi - phiDes;
  var xBal = xOff + footVelGain*(vx-vEff) + footPhiGain*lean + footSpinGain*spin;
  xBal = cl(xBal,-0.45,0.45);

  var bal = balPhi*(1.0+0.15*late)*lean + balSpin*spin + balVel*(vEff-vx);

  var ans = [];

  for (var leg=0; leg<2; leg++) {
    var base = leg ? 10 : 5;
    var hip = num(obs[base],0);
    var hipV = num(obs[base+1],0);
    var knee = num(obs[base+2],0);
    var kneeV = num(obs[base+3],0);
    var foot = obs[base+4] ? 1 : 0;

    var s = f*t + (leg ? legOffset : 0.0);
    s = s - Math.floor(s);

    var stance = (s < duty) ? 1 : 0;
    var u = 0.0, sinu = 0.0, x0 = 0.0;
    var dLeg = dBase;
    var kneeExtra = 0.0;
    var hipExtra = 0.0;

    if (stance) {
      u = (duty > 1e-6) ? (s/duty) : 0.0;
      u = cl(u,0.0,1.0);
      x0 = A*(1.0 - 2.0*u);
      dLeg = dBase + ramp*stancePush*u*u;
    } else {
      var den = 1.0 - duty;
      u = (den > 1e-6) ? ((s-duty)/den) : 0.0;
      u = cl(u,0.0,1.0);
      var uu = u*u*(3.0-2.0*u);
      x0 = -A + 2.0*A*uu;
      sinu = Math.sin(Math.PI*u);

      var clear = lift + terrainLift*obstacle;
      dLeg = dBase - clear*sinu + dropGain*drop*0.5;

      kneeExtra = -swingBend*sinu;
      if (foot && u < 0.80) kneeExtra -= contactRetract;
      hipExtra = hipSwing*sinu;
    }

    var xRel = ramp*(x0 + xBal);
    var dRel = dLeg;

    if (dRel < 0.15) dRel = 0.15;

    var r = Math.sqrt(xRel*xRel + dRel*dRel);
    var maxL = 1.018;
    var minL = 0.672;

    if (r > maxL) {
      var sc1 = maxL/r;
      xRel *= sc1;
      dRel *= sc1;
      r = maxL;
    }
    if (r < minL) {
      var sc2 = minL/(r || 1e-6);
      xRel *= sc2;
      dRel *= sc2;
      r = minL;
    }

    var L = 0.51;
    var cosk = (r*r - 2.0*L*L)/(2.0*L*L);
    cosk = cl(cosk,-1.0,1.0);
    var k0 = -Math.acos(cosk);

    var gamma = Math.atan2(xRel,dRel);

    var hipT = gamma - 0.5*k0 - hipComp*phi + hipBias + ramp*hipExtra;
    var kneeT = k0 + kneeBias + ramp*kneeExtra;

    hipT = cl(hipT,-0.88,1.18);
    kneeT = cl(kneeT,-1.68,-0.06);

    var hipCmd = hipKp*(hipT-hip) - hipKd*hipV;
    var kneeCmd = kneeKp*(kneeT-knee) - kneeKd*kneeV;

    if (stance && foot) {
      kneeCmd += ramp*stanceExt*(0.5 + 0.5*u);
    }

    var w = (1.0-contactWeight) + contactWeight*foot;
    hipCmd += ramp*bal*w;

    if (height < 0.80) {
      var em = cl((0.80-height)/0.30,0.0,1.0);
      kneeCmd += em*0.45;
    }

    if (knee < -1.55) {
      kneeCmd += (-1.55-knee)*5.0;
    }
    if (knee > -0.10 && kneeV > 0.0) {
      kneeCmd -= (knee+0.10)*2.0*Math.max(0.0,kneeV);
    }
    if (hip < -0.80 && hipV < 0.0) {
      hipCmd += (-0.80-hip)*4.0;
    }
    if (hip > 1.10 && hipV > 0.0) {
      hipCmd -= (hip-1.10)*4.0;
    }

    hipCmd = cl(hipCmd,-1.0,1.0);
    kneeCmd = cl(kneeCmd,-1.0,1.0);

    ans.push(hipCmd,kneeCmd);
  }

  return [ans[0],ans[1],ans[2],ans[3]];
}

