  seeds.push(mk({2:0.25,0:0.8,1:0.85,3:0.5,4:0.02,9:1.25,10:1.2,11:0.05,19:3.0,23:0.2,27:0.7}));
  seeds.push(mk({0:0.8,1:0.85,2:0.5,3:0.2,4:0.03,9:1.36,10:0.8,11:0.04,13:10,14:1.5,15:14,16:1.8,17:0.7,19:1.2,20:0.3,21:0.15,22:0.6,24:-0.1,30:0.05,27:0.3,23:0.05}));
  seeds.push(mk({3:1.6,0:1.1,1:0.65,2:1.0,9:1.33,11:0.12,19:2.5}));
  seeds.push(mk({3:0.3,0:1.3,1:0.7,2:0.6,9:1.28}));
  seeds.push(mk({28:1.2,12:1.8,11:0.15,2:0.6,0:1.1,9:1.30}));
  seeds.push(mk({23:0.4,30:0.12,15:22,2:0.8,0:1.2,9:1.30}));
  seeds.push(mk({23:-0.1,30:-0.02,2:0.8,0:1.2}));

  var reserve = 18;
  for (var si=0; si<seeds.length && lab.trialsLeft() > reserve; si++) {
    evalP(seeds[si]);
  }

  var mean = bestAll ? bestAll.slice() : DEF.slice();
  var sigma = new Array(n);
  for (var i0=0;i0<n;i0++) sigma[i0] = (HI[i0]-LO[i0])*0.20;

  var popSize = 26;
  var stall = 0;
  var lastBest = bestAllS;

  while (lab.trialsLeft() > reserve && evals < 965) {
    var Pcount = Math.min(popSize, lab.trialsLeft()-reserve);
    if (Pcount < 6) break;

    var pop = [];
    var sc = [];

    for (var j=0; j<Pcount; j++) {
      var c = null;
      var rnd = Math.random();

      if (j === 0 && bestAll) {
        c = bestAll.slice();
      } else if (j === 1 && bestFull) {
        c = bestFull.slice();
      } else if (j === 2) {
        c = mean.slice();
      } else if (rnd < 0.07 && seeds.length > 0) {
        c = mutate(seeds[Math.floor(Math.random()*seeds.length)], sigma, 1.15);
      } else if (rnd < 0.14 && bestFull) {
        c = mutate(bestFull, sigma, 1.35);
      } else {
        c = mutate(mean, sigma, 1.0);
      }

      c = norm(c);
      pop.push(c);
      sc.push(evalP(c));
    }

    var idx = [];
    for (var j2=0; j2<Pcount; j2++) idx.push(j2);
    idx.sort(function(a,b){ return sc[b] - sc[a]; });

    var E = Math.max(3, Math.floor(Pcount*0.35));
    if (E > Pcount) E = Pcount;

    var newMean = new Array(n);
    for (var i1=0;i1<n;i1++) newMean[i1] = 0.0;

    var wsum = 0.0;
    for (var k=0;k<E;k++) {
      var w = Math.pow(0.72,k);
      var pc = pop[idx[k]];
      for (var i2=0;i2<n;i2++) newMean[i2] += pc[i2]*w;
      wsum += w;
    }
    for (var i3=0;i3<n;i3++) newMean[i3] /= wsum;

    var newSig = new Array(n);
    for (var i4=0;i4<n;i4++) {
      var vv = 0.0;
      var ws = 0.0;
      for (var k2=0;k2<E;k2++) {
        var w2 = Math.pow(0.72,k2);
        var dd = pop[idx[k2]][i4] - newMean[i4];
        vv += w2*dd*dd;
        ws += w2;
      }
      vv = Math.sqrt(vv/ws);

      var rng = HI[i4]-LO[i4];
      var ns = 0.35*sigma[i4] + 0.65*vv;
      if (!isFinite(ns) || ns < rng*0.002) ns = rng*0.002;
      if (ns > rng*0.60) ns = rng*0.60;
      newSig[i4] = ns;
    }

    mean = norm(newMean);
    sigma = newSig;

    if (bestAllS > lastBest + 1e-9) {
      lastBest = bestAllS;
      stall = 0;
    } else {
      stall++;
    }

    if (stall > 6) {
      var pool = candidates.slice();
      pool.sort(function(a,b){ return b.s - a.s; });

      if (pool.length > 0 && Math.random() < 0.75) {
        var pickIdx = Math.floor(Math.random()*Math.min(pool.length,20));
        mean = norm(pool[pickIdx].p.slice());
      } else if (seeds.length > 0) {
        mean = norm(seeds[Math.floor(Math.random()*seeds.length)].slice());
      }

      for (var i5=0;i5<n;i5++) sigma[i5] = (HI[i5]-LO[i5])*0.22;
      stall = 0;
      lastBest = bestAllS;
    }
  }

  function selScore(c) {
    var d = c.d;
    var tt = c.t;
    var s = d + 0.08*tt;
    if (c.full) s += 0.35*d + 0.5;
    if (!c.full) s -= Math.max(0.0,6.0-tt)*0.15;
    return s;
  }

  var bestCand = null;
  var bestCandSel = -1e100;
  for (var ci=0; ci<candidates.length; ci++) {
    var ss = selScore(candidates[ci]);
    if (ss > bestCandSel) {
      bestCandSel = ss;
      bestCand = candidates[ci];
    }
  }

  var baseP = bestCand ? bestCand.p.slice() : (bestAll ? bestAll.slice() : DEF.slice());
  var localScore = bestCand ? bestCand.s : -1e100;
  var rem = lab.trialsLeft() - 2;

  for (var z=0; z<rem; z++) {
    var frac = 1.0 - z/(rem+1.0);
    var c2 = new Array(n);

    for (var i6=0;i6<n;i6++) {
      var rng2 = HI[i6]-LO[i6];
      var sd2 = rng2*(0.025 + 0.085*frac);
      c2[i6] = baseP[i6] + randn()*sd2;
      if (Math.random() < 0.008) c2[i6] = LO[i6] + Math.random()*(HI[i6]-LO[i6]);
    }
    c2 = norm(c2);

    if (bestFull && z % 7 === 0) {
      for (var i7=0;i7<n;i7++) {
        if (Math.random() < 0.40) c2[i7] = bestFull[i7];
      }
      c2 = norm(c2);
    }

    var sc2 = evalP(c2);
    if (sc2 > localScore) {
      localScore = sc2;
      baseP = c2.slice();
    }

    if (z % 24 === 23) {
      var tmpBest = null;
      var tmpSel = -1e100;
      for (var cj=0; cj<candidates.length; cj++) {
        var sj = selScore(candidates[cj]);
        if (sj > tmpSel) {
          tmpSel = sj;
          tmpBest = candidates[cj];
        }
      }
      if (tmpBest && tmpSel > bestCandSel + 1e-9) {
        bestCand = tmpBest;
        bestCandSel = tmpSel;
        baseP = tmpBest.p.slice();
        localScore = Math.max(localScore,tmpBest.s);
      }
    }
  }

  bestCand = null;
  bestCandSel = -1e100;
  for (var cf=0; cf<candidates.length; cf++) {
    var sf = selScore(candidates[cf]);
    if (sf > bestCandSel) {
      bestCandSel = sf;
      bestCand = candidates[cf];
    }
  }

  if (bestCand) return norm(bestCand.p);
  if (bestFull) return norm(bestFull);
  if (bestAll) return norm(bestAll);
  return norm(DEF);
}

function policy(obs, params, mem) {
  var DEF = [2.0,0.60,0.16,0.14,1.38,0.30,0.0,-0.03,
             -0.15,-0.05,0.20,0.90,
             18.0,2.0,35.0,4.0,1.0,0.0,0.0,
             2.0,0.20,0.60,0.80,
             0.01,0.10,0.0,
             1.20,0.15,0.35,0.35,0.50,0.0,
             0.15,0.10,0.03,0.20,0.80,0.0,0.50,0.60,
             0.50,0.50];
  var n = DEF.length;
  var P = (params && typeof params.length === "number" && params.length >= n) ? params : DEF;

  function cl(v,a,b) { return v<a?a:(v>b?b:v); }
  function num(v,d) { return (typeof v === "number" && isFinite(v)) ? v : d; }
  function g(i) { var v = P[i]; return (typeof v === "number" && isFinite(v)) ? v : DEF[i]; }

  var f = cl(g(0),0.25,5.0);
  var duty = cl(g(1),0.25,0.95);
  var A = cl(g(2),0.0,0.50);
  var lift = cl(g(3),0.0,0.50);
  var Hdes = cl(g(4),1.10,1.50);
  var hGain = cl(g(5),0.0,6.0);
  var xOff = cl(g(6),-0.40,0.40);
  var phiDes = cl(g(7),-0.50,0.40);
  var footPhi = cl(g(8),-2.0,2.0);
  var footSpin = cl(g(9),-2.0,2.0);
  var footVel = cl(g(10),-2.0,2.0);
  var vDes = cl(g(11),-0.3,3.0);
  var hipKp = Math.max(0.2,g(12));
  var hipKd = Math.max(0.0,g(13));
  var kneeKp = Math.max(0.2,g(14));
  var kneeKd = Math.max(0.0,g(15));
  var hipComp = cl(g(16),0.0,2.2);
  var hipBias = cl(g(17),-0.6,0.6);
  var kneeBias = cl(g(18),-0.9,0.5);
  var balPhi = cl(g(19),-15.0,15.0);
  var balSpin = cl(g(20),-10.0,10.0);
  var balVel = cl(g(21),-10.0,10.0);
  var contactW = cl(g(22),0.0,1.0);
  var stancePush = cl(g(23),-0.06,0.16);
  var swingBend = cl(g(24),-0.5,1.0);
  var hipSwing = cl(g(25),-0.5,0.5);
  var terrainLift = cl(g(26),0.0,3.0);
  var terrainBody = cl(g(27),0.0,2.0);
  var startDelay = cl(g(28),0.02,1.5);
  var rampTime = cl(g(29),0.02,1.5);
  var legOffset = cl(g(30),0.0,1.0);
  var phase0 = cl(g(31),-1.0,1.0);
  var stanceKneeBoost = cl(g(32),-0.3,0.8);
  var swingRetract = cl(g(33),0.0,0.6);
  var stanceExtend = cl(g(34),0.0,0.30);
  var dropGain = cl(g(35),0.0,1.5);
  var obstacleSlow = cl(g(36),-1.0,3.0);
  var terrainLean = cl(g(37),-3.0,3.0);
  var emergencyKnee = cl(g(38),0.0,1.5);
  var crouchHelp = cl(g(39),0.0,1.0);
  var hipSgn = (g(40) >= 0.0) ? 1.0 : -1.0;
  var kneeSgn = (g(41) >= 0.0) ? 1.0 : -1.0;

  var phi = num(obs[0],0.0);
  var spin = num(obs[1],0.0);
  var vx = num(obs[2],0.0);
  var vy = num(obs[3],0.0);
  var height = num(obs[4],1.0);
  var t = num(obs[19],0.0);

  var a1 = num(obs[15],0.0);
  var a2 = num(obs[16],0.0);
  var a3 = num(obs[17],0.0);
  var a4 = num(obs[18],0.0);

  var obstacle = Math.max(0.0, a1, 0.80*a2, 0.60*a3, 0.40*a4);
  var drop = Math.max(0.0, -a1, -0.80*a2, -0.60*a3, -0.40*a4);

  var late = cl((t - 10.2)/2.5,0.0,1.0);
  late = late*late*(3.0 - 2.0*late);
  var safety = 1.0 + 0.30*late;

  var slow = 1.0 - obstacleSlow*obstacle;
  slow = cl(slow,0.25,1.8);
  var vEff = vDes*slow*(1.0 - 0.20*late);

  var lowC = cl((1.12 - height)/0.38,0.0,1.0);
  var crouch = cl((1.10 - height)/0.35,0.0,1.0);

  var dBase = (Hdes - 0.37) + hGain*(Hdes - height);
  dBase += terrainBody*obstacle;
  dBase += emergencyKnee*lowC*0.18;
  dBase = cl(dBase,0.62,1.02);

  var local = t - startDelay;
  var active = local >= 0.0;
  var stand = !active;

  var ar = 0.0;
  if (active) {
    ar = cl(local/rampTime,0.0,1.0);
    ar = ar*ar*(3.0 - 2.0*ar);
  }

  var Aeff = A*ar*(1.0 - 0.10*late);
  var lifteff = lift*ar;
  var swingBendEff = swingBend*ar;
  var hipSwingEff = hipSwing*ar;

  var lean = phi - phiDes;
  var xBal = xOff + footPhi*lean + footSpin*spin + footVel*(vx - vEff) + terrainLean*obstacle;
  xBal = cl(xBal,-0.55,0.55);
  var bal = (balPhi*lean + balSpin*spin + balVel*(vEff - vx))*safety;

  var ans = [];

  for (var leg=0; leg<2; leg++) {
    var base = leg ? 10 : 5;
    var hip = num(obs[base],0.0);
    var hipV = num(obs[base+1],0.0);
    var knee = num(obs[base+2],0.0);
    var kneeV = num(obs[base+3],0.0);
    var foot = obs[base+4] ? 1.0 : 0.0;

    var s = f*Math.max(0.0,local) + phase0 + (leg ? legOffset : 0.0);
    s = s - Math.floor(s);

    var stance = 1.0;
    var swing = 0.0;
    var u = 0.5;
    var sinu = 0.0;
    var x0 = 0.0;
    var dLeg = dBase;
    var kneeExtra = 0.0;
    var hipExtra = 0.0;

    if (stand) {
      stance = 1.0;
      swing = 0.0;
      u = 0.5;
      x0 = 0.0;
      dLeg = dBase;
    } else if (s < duty) {
      stance = 1.0;
      swing = 0.0;
      u = cl(s / Math.max(0.05,duty),0.0,1.0);
      x0 = Aeff*(1.0 - 2.0*u);
      dLeg = dBase + stancePush*u*u;
      if (!foot) dLeg += stanceExtend*(0.5 + 0.5*u);
      dLeg += crouch*crouchHelp*0.08;
    } else {
      stance = 0.0;
      swing = 1.0;
      var den = Math.max(0.05,1.0 - duty);
      u = cl((s - duty)/den,0.0,1.0);
      var us = u*u*(3.0 - 2.0*u);
      x0 = -Aeff + 2.0*Aeff*us;
      sinu = Math.sin(Math.PI*u);

      var clear = (lift + terrainLift*obstacle)*ar;
      clear *= (1.0 - 0.80*crouch*crouchHelp);
      dLeg = dBase - clear*sinu + dropGain*drop*sinu;
      dLeg += crouch*crouchHelp*0.10;
      if (foot) dLeg -= swingRetract*sinu;

      kneeExtra = -swingBendEff*sinu;
      if (foot) kneeExtra -= swingRetract*2.0*sinu;
      hipExtra = hipSwingEff*sinu;
    }

    var xWanted = x0 + (stand ? 0.25*xBal : xBal);
    var dRel = dLeg;

    var r = Math.sqrt(xWanted*xWanted + dRel*dRel);
    var maxL = 1.018;
    var minL = 0.665;
    if (r > maxL) {
      var sc1 = maxL/(r || 1e-9);
      xWanted *= sc1;
      dRel *= sc1;
      r = maxL;
    }
    if (r < minL) {
      var sc2 = minL/(r || 1e-9);
      xWanted *= sc2;
      dRel *= sc2;
      r = minL;
    }

    var L = 0.51;
    var ck = (r*r - 2.0*L*L)/(2.0*L*L);
    ck = cl(ck,-1.0,1.0);
    var k0 = -Math.acos(ck);
    var gamma = Math.atan2(xWanted,dRel);

    var hipT = gamma - 0.5*k0 - hipComp*phi + hipBias + hipExtra;
    var kneeT = k0 + kneeBias + kneeExtra + crouch*crouchHelp*0.20;

    hipT = cl(hipT,-0.88,1.18);
    kneeT = cl(kneeT,-1.68,-0.06);

    var hipCmd = hipKp*(hipT - hip) - hipKd*hipV;
    var kneeCmd = kneeKp*(kneeT - knee) - kneeKd*kneeV;

    var w = (1.0 - contactW) + contactW*foot;
    hipCmd += bal*w;

    if (stance && foot) kneeCmd += stanceKneeBoost;
    if (!stance && foot) kneeCmd -= swingRetract*2.5;

    if (height < 1.12) {
      var em = cl((1.12 - height)/0.35,0.0,1.0);
      kneeCmd += em*crouchHelp*0.85;
    }

    if (knee < -1.60 && kneeV < 0.0) kneeCmd += (-1.60 - knee)*8.0;
    if (knee > -0.11 && kneeV > 0.0) kneeCmd -= (knee + 0.11)*5.0;
    if (hip < -0.82 && hipV < 0.0) hipCmd += (-0.82 - hip)*6.0;
    if (hip > 1.12 && hipV > 0.0) hipCmd -= (hip - 1.12)*6.0;

    hipCmd = cl(hipCmd,-1.0,1.0);
    kneeCmd = cl(kneeCmd,-1.0,1.0);

    ans.push(cl(hipCmd*hipSgn,-1.0,1.0), cl(kneeCmd*kneeSgn,-1.0,1.0));
  }

  return [ans[0],ans[1],ans[2],ans[3]];
}

function learn(lab) {
  var DEF = [2.0,0.60,0.16,0.14,1.38,0.30,0.0,-0.03,
             -0.15,-0.05,0.20,0.90,
             18.0,2.0,35.0,4.0,1.0,0.0,0.0,
             2.0,0.20,0.60,0.80,
             0.01,0.10,0.0,
             1.20,0.15,0.35,0.35,0.50,0.0,
             0.15,0.10,0.03,0.20,0.80,0.0,0.50,0.60,
             0.50,0.50];
  var LO = [0.50,0.30,0.00,0.00,1.18,0.00,-0.30,-0.40,
            -1.50,-1.50,-1.50,-0.20,
            2.0,0.0,2.0,0.0,0.0,-0.50,-0.80,
            -12.0,-8.0,-8.0,0.0,-0.06,
            -0.50,-0.50,0.0,0.0,0.02,0.02,0.0,-1.0,
            -0.30,0.0,0.0,0.0,
            -1.0,-3.0,0.0,0.0,-1.2,-1.2];
  var HI = [4.50,0.92,0.45,0.45,1.46,5.0,0.30,0.30,
            1.50,1.50,1.50,2.80,
            50.0,10.0,80.0,12.0,2.0,0.50,0.40,
            15.0,10.0,10.0,1.0,0.16,
            1.0,0.50,3.0,2.0,1.50,1.50,1.0,1.0,
            0.80,0.60,0.30,1.50,
            3.0,3.0,1.50,1.0,1.2,1.2];
  var n = DEF.length;

  function cl(v,a,b) { return v<a?a:(v>b?b:v); }
  function randn() {
    var u = 0.0, v = 0.0;
    while (u === 0.0) u = Math.random();
    while (v === 0.0) v = Math.random();
    return Math.sqrt(-2.0*Math.log(u))*Math.cos(2.0*Math.PI*v);
  }
  function norm(p) {
    var q = new Array(n);
    for (var i=0;i<n;i++) {
      var v = (p && typeof p[i] === "number" && isFinite(p[i])) ? p[i] : DEF[i];
      q[i] = cl(v,LO[i],HI[i]);
    }
    return q;
  }
  function mutate(base,sig,scale) {
    var c = new Array(n);
    for (var i=0;i<n;i++) {
      var sd = sig[i]*scale;
      if (Math.random() < 0.025) sd *= 2.5;
      var v = base[i] + randn()*sd;
      if (Math.random() < 0.005) v = LO[i] + Math.random()*(HI[i]-LO[i]);
      c[i] = cl(v,LO[i],HI[i]);
    }
    return norm(c);
  }
  function mk(mods) {
    var p = DEF.slice();
    for (var key in mods) {
      if (!mods.hasOwnProperty(key)) continue;
      var idx = +key;
      if (idx >= 0 && idx < n && typeof mods[key] === "number") p[idx] = mods[key];
    }
    return norm(p);
  }
  function mkFrom(base,mods) {
    var p = base.slice();
    for (var key in mods) {
      if (!mods.hasOwnProperty(key)) continue;
      var idx = +key;
      if (idx >= 0 && idx < n && typeof mods[key] === "number") p[idx] = mods[key];
    }
    return norm(p);
  }
  function distNorm(a,b) {
    var s = 0.0;
    for (var i=0;i<n;i++) {
      var d = (a[i]-b[i])/(HI[i]-LO[i]);
      s += d*d;
    }
    return Math.sqrt(s/n);
  }

  var allRes = [];
  var fullRes = [];
  var bestAllP = null;
  var bestAllScore = -1e100;
  var bestAllInfo = null;
  var bestFullP = null;
  var bestFullD = -1.0;
  var bestFullInfo = null;
  var evals = 0;

  function evalP(p) {
    p = norm(p);
    var r = null;
    try { r = lab.trial(p); } catch (e) { r = null; }
    evals++;

    var info = {
      p: p.slice(),
      valid: false,
      full: false,
      d: 0.0,
      t: 0.0,
      out: "error",
      energy: 0.0,
      score: -1e100
    };

    if (r) {
      var out = (typeof r.outcome === "string") ? r.outcome : "";
      info.out = out;
      if (out !== "invalid" && out !== "error") {
        info.valid = true;
        var d = +r.distance;
        if (!isFinite(d) || d < 0.0) d = 0.0;
        var tt = +r.time;
        if (!isFinite(tt) || tt < 0.0) tt = 0.0;
        if (tt > 10.0) tt = 10.0;
        var en = +r.energy;
        if (!isFinite(en) || en < 0.0) en = 0.0;

        info.d = d;
        info.t = tt;
        info.energy = en;

        var full = (out === "finished") || (tt >= 9.98 && out !== "fell");
        info.full = full;

        if (full) {
          info.score = 1e7 + d*1000.0 + tt*5.0 - en*0.0001;
        } else {
          info.score = d*100.0 + tt*200.0;
        }
      }
    }

    allRes.push(info);

    if (info.score > bestAllScore) {
      bestAllScore = info.score;
      bestAllP = info.p.slice();
      bestAllInfo = info;
    }
    if (info.full) {
      fullRes.push(info);
