    const p = {};
    for (const k of KEYS) p[k] = RANGES[k][0] + Math.random() * (RANGES[k][1] - RANGES[k][0]);
    return p;
  };
  const mutate = (parent, sigma) => {
    const p = {};
    for (const k of KEYS) {
      const [lo, hi] = RANGES[k];
      p[k] = clampVal(parent[k] + gauss() * sigma * (hi - lo), lo, hi);
    }
    return p;
  };

  let best = null, bestS = -Infinity;
  let evals = 0;
  const maxEvals = 500;

  const evaluate = (p) => {
    if (lab.trialsLeft() <= 0 || evals >= maxEvals || timeUp()) return null;
    evals++;
    let r;
    try { r = lab.trial(p); } catch (e) { return -1; }
    if (!r || r.outcome === 'invalid' || r.outcome === 'error') return -1;
    const s = (r.distance || 0) + (r.outcome === 'finished' ? 5 : 0);
    if (s > bestS) { bestS = s; best = p; }
