  let parentS = evaluate(defaults);
  if (parentS === null) return best || defaults;
  for (let i = 0; i < 60; i++) {
    const p = randomP();
    const s = evaluate(p);
    if (s === null) return best || defaults;
    if (s > parentS) { parentS = s; parent = p; }
  }

