    const child = mutate(parent, sigma);
    const s = evaluate(child);
    if (s === null) break;
    tries++;
    if (s > parentS) {
      parentS = s; parent = child; successes++;
    }
    if (tries >= 20) {
      const rate = successes / tries;
      if (rate > 0.2) sigma = Math.min(0.5, sigma * 1.2);
      else sigma = Math.max(0.01, sigma * 0.82);
      tries = 0; successes = 0;
    }
  }

  return best || parent || defaults;
