  const hipTA = clampVal(hipMid + corr + hipAmp * Math.cos(phA), -0.9, 1.2);
  const hipTB = clampVal(hipMid + corr + hipAmp * Math.cos(phB), -0.9, 1.2);
  const kneeTA = clampVal(kneeMid - kneeAmp * Math.max(0, Math.sin(phA + kneeOff)) - lift, -1.7, -0.05);
  const kneeTB = clampVal(kneeMid - kneeAmp * Math.max(0, Math.sin(phB + kneeOff)) - lift, -1.7, -0.05);

  const hipA = fin(obs[5], 0), hipAS = fin(obs[6], 0);
  const kneeA = fin(obs[7], 0), kneeAS = fin(obs[8], 0);
  const hipB = fin(obs[10], 0), hipBS = fin(obs[11], 0);
  const kneeB = fin(obs[12], 0), kneeBS = fin(obs[13], 0);

  const u0 = clampVal(kp * (hipTA - hipA) - kd * hipAS, -1, 1);
  const u1 = clampVal(kp * (kneeTA - kneeA) - kd * kneeAS, -1, 1);
  const u2 = clampVal(kp * (hipTB - hipB) - kd * hipBS, -1, 1);
  const u3 = clampVal(kp * (kneeTB - kneeB) - kd * kneeBS, -1, 1);
  return [u0, u1, u2, u3].map(x => (isFinite(x) ? x : 0));
}

function learn(lab) {
  const now = () => (typeof Date !== 'undefined' ? Date.now() : 0);
  const t0 = now();
  const timeUp = () => now() - t0 > 150000;
  const clamp01 = x => (x < 0 ? 0 : (x > 1 ? 1 : x));
  const D = KEYS.length;

  const gauss = () => {
    const u = Math.max(1e-12, Math.random());
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const toP = u => {
    const p = {};
    for (let i = 0; i < D; i++) {
      const k = KEYS[i], lo = RANGES[k][0], hi = RANGES[k][1];
      p[k] = lo + u[i] * (hi - lo);
    }
    return p;
  };
  const toU = p => KEYS.map(k => {
    const lo = RANGES[k][0], hi = RANGES[k][1];
    const v = (typeof p[k] === 'number' && isFinite(p[k])) ? p[k] : (lo + hi) / 2;
    return clamp01((v - lo) / (hi - lo));
  });
  const randU = () => KEYS.map(() => Math.random());

  let best = null, bestS = -Infinity, bestU = null;
  const archive = [];
  let stop = false;

  const evaluate = u => {
    if (stop) return null;
    if (lab.trialsLeft() <= 0 || timeUp()) { stop = true; return null; }
    const p = toP(u);
    let r;
    try { r = lab.trial(p); } catch (e) { return -1; }
    let s;
    if (!r || r.outcome === 'invalid' || r.outcome === 'error') {
      s = -1;
    } else {
      const d = (typeof r.distance === 'number' && isFinite(r.distance)) ? r.distance : 0;
      s = d + (r.outcome === 'finished' ? 5 : 0);
    }
    archive.push({ u: u, s: s });
    if (s > bestS) { bestS = s; best = p; bestU = u; }
    return s;
  };

  const topK = k => archive.slice().sort((a, b) => b.s - a.s).slice(0, k);

  // Phase 1: the attempt-5 gait (best race so far) and the attempt-4 gait.
  const seeds = [toU(SEED_A5), toU(SEED_A4)];
  for (const u of seeds) {
    if (evaluate(u) === null) break;
  }
  if (stop) return best || SEED_A5;

  // Phase 2: small local search around the best known gait with restarts
  // from elite points. No wide random restarts: the space is mostly falls.
  const LAM = 10, MU = 3;
  const wts = [];
  for (let i = 0; i < MU; i++) wts.push(Math.log(MU + 0.5) - Math.log(i + 1));

  let mean = bestU ? bestU.slice() : toU(SEED_A5);
  let sigma = 0.05;
  let stall = 0;

  while (!stop) {
    if (lab.trialsLeft() <= 0 || timeUp()) break;
    const before = bestS;
    const pop = [];
    for (let k = 0; k < LAM && !stop; k++) {
      const u = mean.map(x => clamp01(x + sigma * gauss()));
      const s = evaluate(u);
      if (s === null) break;
      pop.push({ u: u, s: s });
    }
    if (pop.length === 0) break;

    pop.sort((a, b) => b.s - a.s);
    const m = Math.min(MU, pop.length);
    let wsub = 0;
    for (let i = 0; i < m; i++) wsub += wts[i];
    mean = mean.map((_, d) => {
      let acc = 0;
      for (let i = 0; i < m; i++) acc += wts[i] * pop[i].u[d];
      return clamp01(acc / wsub);
    });

    if (bestS > before + 1e-9) {
      sigma = Math.min(0.15, sigma * 1.2);
      stall = 0;
    } else {
      sigma = Math.max(0.01, sigma * 0.93);
      stall++;
    }

    if (stall >= 8 && !stop) {
      stall = 0;
      const top = topK(6);
      if (top.length > 0) {
        mean = top[Math.floor(Math.random() * top.length)].u.slice();
      }
      sigma = 0.06;
    }
  }

  return best || SEED_A5;
}

const RANGES = {
  freq:    [0.8, 4.0],
  hipMid:  [-0.4, 1.0],
  hipAmp:  [0.0, 1.2],
  kneeMid: [-1.3, -0.2],
  kneeAmp: [0.0, 1.2],
  kneeOff: [0.0, 6.2832],
  legOff:  [0.0, 6.2832],
  balAng:  [-3.0, 3.0],
  balSpin: [-0.5, 0.5],
  balV:    [-0.4, 0.4],
  kp:      [2.0, 15.0],
  kd:      [0.0, 0.6],
  eps:     [0.0, 1.5],
  lean:    [-0.5, 0.8]
};
const KEYS = Object.keys(RANGES);

// Attempt 5's returned best (race 6.68 m, survived 20 s).
const SEED_A5 = {
  freq: 3.2, hipMid: 0.6, hipAmp: 0.9,
  kneeMid: -1.2426150660461062, kneeAmp: 0.38265755004612856, kneeOff: 2.5181808254055955,
  legOff: 2.3953910319201017, balAng: 0.09472898106976047, balSpin: 0.03727148794658375,
  balV: -0.14395415220699687, kp: 6.014157099564502, kd: 0.2131875767498407,
  eps: 1.2862643226446164, lean: 0.2880704157136378
};

function clampVal(x, lo, hi) { return x < lo ? lo : (x > hi ? hi : x); }
function fin(x, d) { return (typeof x === 'number' && isFinite(x)) ? x : d; }

function policy(obs, p, mem) {
  p = p || {};
  const freq = fin(p.freq, 1.5);
  const hipMid = fin(p.hipMid, 0.1);
  const hipAmp = fin(p.hipAmp, 0.4);
  const kneeMid = fin(p.kneeMid, -0.8);
  const kneeAmp = fin(p.kneeAmp, 0.5);
  const kneeOff = fin(p.kneeOff, 1.0);
  const legOff = fin(p.legOff, Math.PI);
  const balAng = fin(p.balAng, 1.0);
  const balSpin = fin(p.balSpin, 0.1);
  const balV = fin(p.balV, 0.0);
  const kp = fin(p.kp, 6.0);
  const kd = fin(p.kd, 0.2);
  const eps = fin(p.eps, 0.0);
  const lean = fin(p.lean, 0.0);

  const t = fin(obs[19], 0);
  const torsoAngle = fin(obs[0], 0);
  const torsoSpin = fin(obs[1], 0);
  const vx = fin(obs[2], 0);

  // Phase oscillator advanced by real elapsed time.
  if (typeof mem.last !== 'number') { mem.last = t; mem.phase = 0; }
  let dt = t - mem.last;
  if (!(dt > 0)) dt = 0;
  if (dt > 0.1) dt = 0.1;
  mem.last = t;
  mem.phase = (typeof mem.phase === 'number' ? mem.phase : 0) + 2 * Math.PI * freq * dt;

  let phA = mem.phase;
  // Entrain the phase to the measured hip A motion.
  if (eps > 0 && hipAmp > 0.02) {
    const hipA0 = fin(obs[5], 0);
    const err = (hipA0 - hipMid) - hipAmp * Math.cos(phA);
    let c = -eps * err * hipAmp * Math.sin(phA) / (hipAmp * hipAmp + 0.01);
    c = clampVal(c, -0.08, 0.08);
    if (isFinite(c)) { phA += c; mem.phase += c; }
  }
  const phB = phA + legOff;

  // Balance feedback on the hips, with a learnable torso-lean setpoint.
  const corr = balAng * (torsoAngle - lean) + balSpin * torsoSpin + balV * vx;

  // Hurdle / rising-ground reaction: lift knees when ground is higher ahead.
  const ahead1 = fin(obs[15], 0);
  const ahead2 = fin(obs[16], 0);
  const rise = Math.max(ahead1 - 0.02, 0.6 * (ahead2 - 0.02));
  const lift = clampVal(rise, 0, 0.6) * 1.5;

  const hipTA = clampVal(hipMid + corr + hipAmp * Math.cos(phA), -0.9, 1.2);
  const hipTB = clampVal(hipMid + corr + hipAmp * Math.cos(phB), -0.9, 1.2);
  const kneeTA = clampVal(kneeMid - kneeAmp * Math.max(0, Math.sin(phA + kneeOff)) - lift, -1.7, -0.05);
  const kneeTB = clampVal(kneeMid - kneeAmp * Math.max(0, Math.sin(phB + kneeOff)) - lift, -1.7, -0.05);

  const hipA = fin(obs[5], 0), hipAS = fin(obs[6], 0);
  const kneeA = fin(obs[7], 0), kneeAS = fin(obs[8], 0);
  const hipB = fin(obs[10], 0), hipBS = fin(obs[11], 0);
  const kneeB = fin(obs[12], 0), kneeBS = fin(obs[13], 0);

  const u0 = clampVal(kp * (hipTA - hipA) - kd * hipAS, -1, 1);
  const u1 = clampVal(kp * (kneeTA - kneeA) - kd * kneeAS, -1, 1);
  const u2 = clampVal(kp * (hipTB - hipB) - kd * hipBS, -1, 1);
  const u3 = clampVal(kp * (kneeTB - kneeB) - kd * kneeBS, -1, 1);
  return [u0, u1, u2, u3].map(x => (isFinite(x) ? x : 0));
}

function learn(lab) {
  const now = () => (typeof Date !== 'undefined' ? Date.now() : 0);
  const t0 = now();
  const timeUp = () => now() - t0 > 140000;
  const clamp01 = x => (x < 0 ? 0 : (x > 1 ? 1 : x));
  const D = KEYS.length;

  const gauss = () => {
    const u = Math.max(1e-12, Math.random());
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const toP = u => {
    const p = {};
    for (let i = 0; i < D; i++) {
      const k = KEYS[i], lo = RANGES[k][0], hi = RANGES[k][1];
      p[k] = lo + u[i] * (hi - lo);
    }
    return p;
  };
  const toU = p => KEYS.map(k => {
    const lo = RANGES[k][0], hi = RANGES[k][1];
    const v = (typeof p[k] === 'number' && isFinite(p[k])) ? p[k] : (lo + hi) / 2;
    return clamp01((v - lo) / (hi - lo));
  });

  let best = null, bestS = -Infinity;
  let stop = false;

  const evaluate = u => {
    if (stop) return null;
    if (lab.trialsLeft() <= 0 || timeUp()) { stop = true; return null; }
    const p = toP(u);
    let r;
    try { r = lab.trial(p); } catch (e) { stop = true; return null; }
    let s;
    if (!r || r.outcome === 'invalid' || r.outcome === 'error') {
      s = -1;
    } else {
      const d = (typeof r.distance === 'number' && isFinite(r.distance)) ? r.distance : 0;
      s = d + (r.outcome === 'finished' ? 5 : 0);
    }
    if (s > bestS) { bestS = s; best = p; }
    return s;
  };

  // Seed: attempt 5's gait, the best raced so far.
  const uA = toU(SEED_A5);
  let mean = uA.slice();
  let parentS = evaluate(uA);
  if (parentS === null) return SEED_A5;

  // Conservative (1+1)-style local search around the seed.
  // A child replaces the parent only if it scores at least as well.
  let sigma = 0.04;
  let fails = 0;
  while (!stop) {
    if (lab.trialsLeft() <= 0 || timeUp()) break;
    const child = mean.map(x => clamp01(x + sigma * gauss()));
    const s = evaluate(child);
    if (s === null) break;
    if (s >= parentS) {
      if (s > parentS + 1e-9) fails = 0;
      mean = child;
      parentS = s;
      sigma = Math.min(0.08, sigma * 1.1);
    } else {
      fails++;
      sigma = Math.max(0.01, sigma * 0.97);
      if (fails >= 40) {
        // Restart from the best point found so far.
        fails = 0;
        if (best) mean = toU(best);
        sigma = 0.05;
      }
    }
  }

  return best || SEED_A5;
}
